#### **ModelPiece** (Lines ~37527-37695) - **CORE HOVER IMPLEMENTATION**

This is where hover event handlers are attached to 3D objects:

```typescript
const ModelPiece: FC<ModelPieceProps> = () => {
  const piece = usePiece() as Piece;
  const isSelected = useIsPieceSelected();
  const isHovered = useIsPieceTransitiveHovered();  // ⭐ Gets hover state
  const status = usePieceStatus();

  const [hoverPiece] = useDesignAppHoverPiece();      // ⭐ Hover action
  const [clearHover] = useDesignAppClearHover();      // ⭐ Clear action
  const { currentHoveredPieceGuidRef } = useHoverIntent();

  // ⭐ MOUSE ENTER - Called when pointer enters 3D piece
  const handlePointerEnter = useCallback(() => {
    if (currentHoveredPieceGuidRef.current !== piece.guid) {
      currentHoveredPieceGuidRef.current = piece.guid;
      if (hoverPiece) hoverPiece(piece.guid);  // Set hover state in store
    }
  }, [piece.guid, hoverPiece, currentHoveredPieceGuidRef]);

  // ⭐ MOUSE LEAVE - Called when pointer leaves 3D piece
  const handlePointerLeave = useCallback(() => {
    if (currentHoveredPieceGuidRef.current === piece.guid) {
      currentHoveredPieceGuidRef.current = null;
      if (clearHover) clearHover();  // Clear hover state
    }
  }, [piece.guid, clearHover, currentHoveredPieceGuidRef]);

  // Compute highlight color based on selection/hover state
  const highlightColor = useMemo(() => 
    (isSelected ? activeBaseColor : isHovered ? hoverBaseColor : null),
    [isSelected, isHovered, activeBaseColor, hoverBaseColor]
  );

  // Render geometry or mesh with handlers
  const diffedMeshContent = piece.design ? (
    <Geometry
      selected={isSelected}
      hovered={isHovered}
      onClick={onSelect}
      onDoubleClick={onDoubleClick}
      onPointerEnter={handlePointerEnter}  // ⭐ Attach hover enter
      onPointerLeave={handlePointerLeave}  // ⭐ Attach hover leave
      color={materialColor}
      emissiveColor={emissiveColor}
      showEdges
      userData={userData}
    />
  ) : (
    <group userData={userData}>
      <PieceMesh 
        highlightColor={highlightColor}
        onClick={onSelect}
        onDoubleClick={onDoubleClick}
        onPointerEnter={handlePointerEnter}  // ⭐ Attach hover enter
        onPointerLeave={handlePointerLeave}  // ⭐ Attach hover leave
      />
    </group>
  );

  return (
    <>
      {originalMeshContent}
      {pieceMatrix && (
        <group userData={userData} matrix={pieceMatrix} matrixAutoUpdate={false}>
          {diffedMeshContent}
        </group>
      )}
    </>
  );
};
```

