### **6. Hover State Actions (Lines ~29835-29950)**

These hooks dispatch actions to the state manager:

```typescript
// Set hover to single piece
export function useDesignAppHoverPiece(): ActionHookResult<[pieceGuid: string]> {
  const [, setHover, canSetHover] = useDesignAppHover();
  const action = useMemo(() => {
    if (!canSetHover || !setHover) return undefined;
    return (pieceGuid: string) => setHover({ pieces: [pieceGuid] });
  }, [setHover, canSetHover]);
  return [action, canSetHover];
}

// Clear all hover state
export function useDesignAppClearHover(): ActionHookResult<[]> {
  const [, setHover, canSetHover] = useDesignAppHover();
  const action = useMemo(() => {
    if (!canSetHover || !setHover) return undefined;
    return () => setHover(undefined);
  }, [setHover, canSetHover]);
  return [action, canSetHover];
}

// Also available:
useDesignAppHoverPieces()      // Multiple pieces
useDesignAppHoverConnection()  // Single connection
useDesignAppHoverPort()        // Port (piece + connector)
useDesignAppHoverTypes()       // Multiple types
useDesignAppHoverDesigns()     // Multiple designs
```

